export type Transmission = 'Automatic' | 'Manual';
export type CarStatus = 'available' | 'unavailable';
export type BookingStatus = 'pending' | 'confirmed' | 'cancelled' | 'completed';

export interface User {
  id: string;
  name: string;
  email: string;
  role: Role;
  avatar_url: string;
}

export interface CarLocation {
  city: string;
