  id: string;
  owner_id: string;
  title: string;
  brand: string;
  model: string;
  year: number;
  daily_rate: number;
  cleaning_fee: number;
  location: CarLocation;
  pickup_instructions: string;
  specs: CarSpecs;
  image_url: string;
  status: CarStatus;
}

export interface CarInput {
  title?: string;
  brand: string;
  model: string;
  year: number;
  daily_rate: number;
  cleaning_fee: number;
  location: CarLocation;
  pickup_instructions: string;
  specs: CarSpecs;
  image_url: string;
