  });

  it('matches location against city, state and address', () => {
    expect(filterCars(cars, { ...noFilters, location: 'denver' })).toHaveLength(1);
    expect(filterCars(cars, { ...noFilters, location: 'ca' }).map((c) => c.id)).toContain('car_03');
