  it('ignores a negative max price', () => {
    expect(filterCars(cars, { ...noFilters, maxPrice: '-5' })).toHaveLength(3);
  });

  it('filters by transmission exactly', () => {
    expect(filterCars(cars, { ...noFilters, transmission: 'Manual' })).toHaveLength(0);
