import { useCallback, useState, type FormEvent } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { api, ApiRequestError } from './api';
import {
  AccessDenied,
  AvailabilityBadge,
  BookingCard,
  CarCard,
  CarImage,
  ConfirmDialog,
  Field,
  LoadState,
  PriceBreakdown,
} from './components';
import { useAsync, useSession, useToast } from './hooks';
import {
  DATE_MESSAGES,
  calcDays,
