html, body, #root { min-height: 100%; }
#root { display: flex; flex-direction: column; min-height: 100vh; }
h1, h2, h3, p { margin: 0; }
a { color: var(--color-primary); }
button, input, select, textarea { font: inherit; color: inherit; }

.header { background: var(--color-header-bg); color: var(--color-header-text); }
.header-inner {
  max-width: var(--width-content); margin: 0 auto; padding: var(--space-3) var(--space-4);
  display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-3) var(--space-5);
}
.brand { color: var(--color-header-text); font-weight: var(--font-weight-bold); font-size: var(--font-size-lg); text-decoration: none; }
.nav { display: flex; flex-wrap: wrap; gap: var(--space-4); order: 3; width: 100%; }
.nav-link { color: var(--color-header-text); text-decoration: none; padding: var(--space-2) 0; border-bottom: 3px solid transparent; opacity: 0.85; }
.nav-link:hover { opacity: 1; }
.nav-link[aria-current='page'] { border-bottom-color: var(--color-header-text); opacity: 1; font-weight: var(--font-weight-bold); }
.user-area { display: flex; align-items: center; gap: var(--space-3); margin-left: auto; min-width: 0; }
.avatar { width: 32px; height: 32px; border-radius: var(--radius-pill); object-fit: cover; background: var(--color-surface-muted); flex: none; }
.avatar-fallback { display: inline-flex; align-items: center; justify-content: center; color: var(--color-text); font-weight: var(--font-weight-bold); }
.current-user { font-size: var(--font-size-sm); display: none; }
.switcher {
  height: var(--control-height-sm); border-radius: var(--radius-sm); border: 1px solid var(--color-border);
  background: var(--color-surface); color: var(--color-text); padding: 0 var(--space-2); max-width: 200px;
}

.content { flex: 1; width: 100%; max-width: var(--width-content); margin: 0 auto; padding: var(--space-5) var(--space-4); }
.footer { text-align: center; padding: var(--space-4); color: var(--color-text-muted); }
.page-title { font-size: var(--font-size-xl); font-weight: var(--font-weight-bold); margin-bottom: var(--space-4); }
.title-row { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: var(--space-3); margin-bottom: var(--space-4); }
.title-row .page-title { margin-bottom: 0; }
h2 { font-size: var(--font-size-lg); }
.muted { color: var(--color-text-muted); }
.small { font-size: var(--font-size-sm); }
.small-heading { font-size: var(--font-size-md); margin-top: var(--space-4); }
.back-link { display: inline-block; margin-bottom: var(--space-4); }

.card { background: var(--color-surface); border-radius: var(--radius-md); box-shadow: var(--shadow-card); }
.card-body { padding: var(--space-4); }
.card-body > * + * { margin-top: var(--space-2); }

.btn {
  display: inline-flex; align-items: center; justify-content: center; height: var(--control-height);
  padding: 0 var(--space-4); border-radius: var(--radius-sm); border: 1px solid transparent;
  font-weight: var(--font-weight-bold); cursor: pointer; text-decoration: none; background: none;
}
.btn-sm { height: var(--control-height-sm); }
.btn-block { width: 100%; }
.btn-primary { background: var(--color-primary); color: var(--color-primary-text); }
.btn-primary:hover:not(:disabled) { background: var(--color-primary-hover); }
.btn-secondary { background: var(--color-surface); color: var(--color-text); border-color: var(--color-border); }
.btn-secondary:hover:not(:disabled) { background: var(--color-surface-muted); }
.btn-danger { background: var(--color-danger); color: var(--color-text-inverse); }
.btn-danger:hover:not(:disabled) { background: var(--color-danger-hover); }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }

.field { margin-bottom: var(--space-3); min-width: 0; }
.field label { display: block; font-size: var(--font-size-sm); font-weight: var(--font-weight-medium); margin-bottom: var(--space-1); }
.field input, .field select, .field textarea {
  width: 100%; min-height: var(--control-height); border: 1px solid var(--color-border);
  border-radius: var(--radius-sm); padding: 0 var(--space-3); background: var(--color-surface);
}
