.detail-head { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-3); }
.detail-head h1 { font-size: var(--font-size-xl); }
.spec-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-3); margin: 0; }
.spec-list div { background: var(--color-surface); border-radius: var(--radius-sm); padding: var(--space-3); box-shadow: var(--shadow-card); }
.spec-list dt { font-size: var(--font-size-xs); color: var(--color-text-muted); text-transform: uppercase; letter-spacing: 0.04em; }
.spec-list dd { margin: 0; font-weight: var(--font-weight-bold); }
.panel { padding: var(--space-4); }
.panel h2 { margin-bottom: var(--space-3); }

.breakdown { margin: 0 0 var(--space-4); }
.breakdown div { display: flex; justify-content: space-between; padding: var(--space-1) 0; }
.breakdown dt { color: var(--color-text-muted); }
.breakdown dd { margin: 0; font-weight: var(--font-weight-medium); }
.breakdown-total { border-top: 1px solid var(--color-border); margin-top: var(--space-2); padding-top: var(--space-2) !important; }
.breakdown-total dt, .breakdown-total dd { color: var(--color-text); font-weight: var(--font-weight-bold); font-size: var(--font-size-lg); }
.notice { background: var(--color-warning-bg); color: var(--color-warning); padding: var(--space-3); border-radius: var(--radius-sm); margin-bottom: var(--space-3); }
.notice-success { background: var(--color-success-bg); color: var(--color-success); }
.panel .field-error { margin-bottom: var(--space-3); }

.group { margin-bottom: var(--space-5); }
.group h2 { margin-bottom: var(--space-3); }
.count { color: var(--color-text-muted); font-weight: var(--font-weight-regular); }
.stack { display: flex; flex-direction: column; gap: var(--space-4); }

.booking-card, .listing-row { display: flex; flex-direction: column; gap: var(--space-4); padding: var(--space-4); }
.booking-thumb { width: 100%; aspect-ratio: 16 / 10; object-fit: cover; border-radius: var(--radius-sm); background: var(--color-surface-muted); display: block; }
.booking-card .image-fallback, .listing-row .image-fallback { border-radius: var(--radius-sm); }
.booking-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: var(--space-1); }
.booking-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--space-2); }
.booking-head h3, .listing-title { font-size: var(--font-size-lg); }
.total { color: var(--color-text); }
.actions { display: flex; flex-wrap: wrap; gap: var(--space-2); margin-top: var(--space-3); }

.tabs { display: flex; flex-wrap: wrap; gap: var(--space-2); margin-bottom: var(--space-4); }
.tab { height: var(--control-height-sm); padding: 0 var(--space-4); border-radius: var(--radius-pill); border: 1px solid var(--color-border); background: var(--color-surface); cursor: pointer; font-weight: var(--font-weight-medium); }
.tab[aria-pressed='true'] { background: var(--color-primary); color: var(--color-primary-text); border-color: var(--color-primary); }

.narrow-form { max-width: var(--width-form); margin: 0 auto; }
.form-card { padding: var(--space-4); }
.form-grid { display: grid; grid-template-columns: 1fr; gap: 0 var(--space-4); }

.stat-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-4); margin-bottom: var(--space-5); }
.stat { padding: var(--space-4); }
.stat-label { color: var(--color-text-muted); font-size: var(--font-size-sm); }
.stat-value { font-size: var(--font-size-xl); font-weight: var(--font-weight-bold); overflow-wrap: anywhere; }
.table-wrap { overflow-x: auto; background: var(--color-surface); border-radius: var(--radius-md); box-shadow: var(--shadow-card); margin-top: var(--space-3); }
.table { width: 100%; border-collapse: collapse; }
.table th, .table td { text-align: left; padding: var(--space-3) var(--space-4); border-bottom: 1px solid var(--color-border); }
.table th { font-size: var(--font-size-sm); color: var(--color-text-muted); }

.toasts { position: fixed; top: 72px; left: var(--space-4); right: var(--space-4); z-index: 50; display: flex; flex-direction: column; align-items: flex-end; pointer-events: none; }
.toast { pointer-events: auto; display: flex; align-items: center; gap: var(--space-3); padding: var(--space-3) var(--space-4); border-radius: var(--radius-sm); box-shadow: var(--shadow-raised); max-width: 100%; }
.toast-success { background: var(--color-success-bg); color: var(--color-success); }
.toast-error { background: var(--color-danger-bg); color: var(--color-danger); }
.toast-dismiss { background: none; border: 0; text-decoration: underline; cursor: pointer; color: inherit; font-size: var(--font-size-sm); }

.dialog-backdrop { position: fixed; inset: 0; background: rgba(15, 27, 45, 0.5); display: flex; align-items: center; justify-content: center; padding: var(--space-4); z-index: 60; }
.dialog { background: var(--color-surface); border-radius: var(--radius-md); padding: var(--space-5); max-width: 440px; width: 100%; box-shadow: var(--shadow-raised); display: flex; flex-direction: column; gap: var(--space-3); }
.dialog-actions { display: flex; justify-content: flex-end; gap: var(--space-2); margin-top: var(--space-2); }

@media (min-width: 480px) {
  .current-user { display: inline; }
}

@media (min-width: 768px) {
  .header-inner { padding: var(--space-3) var(--space-5); flex-wrap: nowrap; }
  .nav { order: 0; width: auto; }
  .content { padding: var(--space-5); }
  .filter-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .form-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .stat-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .toasts { left: auto; right: var(--space-5); top: 76px; }
  .booking-card, .listing-row { flex-direction: row; align-items: flex-start; }
  .booking-thumb { width: 200px; flex: none; }
  .listing-row .actions { margin-top: 0; flex-direction: column; align-items: stretch; }
}

@media (min-width: 1024px) {
  .detail-layout { grid-template-columns: minmax(0, 1fr) var(--width-booking-panel); }
  .panel { position: sticky; top: var(--space-4); }
  .spec-list { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
